let body = $json.body ?? $json;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {}
}

const cfg = {
  templateDocId: body.config?.templateDocId || 'YOUR_TEMPLATE_DOC_ID',
  outputDocFolderId: body.config?.outputDocFolderId || 'YOUR_OUTPUT_DOC_FOLDER_ID',
};

function safeText(value) {
  return String(value || '')
    .trim()
    .replace(/[\\/:*?"<>|]/g, '')
    .replace(/\s+/g, ' ');
}

function formatTanggal(value) {
  return String(value || '')
    .trim()
    .replace(/\//g, '-')
    .replace(/\s+/g, ' ');
}

const namaSite = safeText(body.textPlaceholders?.['<<Lokasi Site>>'] || 'SITE');
const kunjunganKe = safeText(body.textPlaceholders?.['<<Keterangan Kunjungan>>'] || 'Kunjungan');
const tanggalKunjungan = formatTanggal(body.textPlaceholders?.['<<Tanggal Kunjungan>>'] || '');

const reportName = safeText(
  body.reportName || `Laporan Visit ${namaSite} ${kunjunganKe} ${tanggalKunjungan}`.trim()
);

const recipientEmail = body.recipientEmail || body.textPlaceholders?.['<<Email>>'] || '';
const textPlaceholders = body.textPlaceholders || {};
const imagePlaceholders = Array.isArray(body.imagePlaceholders) ? body.imagePlaceholders : [];

if (!cfg.templateDocId) {
  throw new Error('templateDocId belum diisi.');
}
if (!cfg.outputDocFolderId) {
  throw new Error('outputDocFolderId belum diisi.');
}

const cleanImages = imagePlaceholders
  .filter(x => x && x.placeholder)
  .map(x => {
    const fileId = String(x.fileId || '').trim();
    let publicImageUrl = String(x.publicImageUrl || '').trim();

    // Fallback otomatis jika hanya fileId Google Drive yang dikirim
    if (!publicImageUrl && fileId) {
      publicImageUrl = `https://lh3.googleusercontent.com/d/${fileId}`;
    }

    return {
      placeholder: String(x.placeholder || '').trim(),
      fileId,
      publicImageUrl,
    };
  });

return [{
  json: {
    config: cfg,
    reportName,
    recipientEmail,
    textPlaceholders,
    imagePlaceholders: cleanImages,
    originalPayload: body,
  }
}];

const textPlaceholders = $items('Normalize Payload', 0, 0)[0].json.textPlaceholders || {};
const requests = [];

for (const [placeholder, value] of Object.entries(textPlaceholders)) {
  requests.push({
    replaceAllText: {
      containsText: { text: placeholder, matchCase: true },
      replaceText: value == null ? '' : String(value),
    },
  });
}

// Pengaman agar Google Docs API tidak 400 jika textPlaceholders kosong
if (requests.length === 0) {
  requests.push({
    replaceAllText: {
      containsText: { text: '[[NOOP_EMPTY_TEXT]]', matchCase: true },
      replaceText: '',
    },
  });
}

return [{
  json: {
    documentId: $json.id,
    docUrl: `https://docs.google.com/document/d/${$json.id}/edit`,
    reportName: $items('Normalize Payload', 0, 0)[0].json.reportName,
    recipientEmail: $items('Normalize Payload', 0, 0)[0].json.recipientEmail,
    imagePlaceholders: $items('Normalize Payload', 0, 0)[0].json.imagePlaceholders,
    requests,
    originalPayload: $items('Normalize Payload', 0, 0)[0].json.originalPayload,
  }
}];

const document = $json;
const base = $items('Build Text Requests', 0, 0)[0].json;
const imagePlaceholders = Array.isArray(base.imagePlaceholders) ? base.imagePlaceholders : [];

const textElements = [];

function scan(elements = []) {
  for (const el of elements) {
    if (el.paragraph?.elements) {
      for (const pe of el.paragraph.elements) {
        const content = pe.textRun?.content || '';
        if (content) {
          textElements.push({
            startIndex: pe.startIndex,
            endIndex: pe.endIndex,
            content,
          });
        }
      }
    }

    if (el.table?.tableRows) {
      for (const row of el.table.tableRows || []) {
        for (const cell of row.tableCells || []) {
          scan(cell.content || []);
        }
      }
    }

    if (el.tableOfContents?.content) {
      scan(el.tableOfContents.content || []);
    }
  }
}

scan(document.body?.content || []);

const allTokens = [];
for (const t of textElements) {
  const regex = /<<[^>]+>>/g;
  let m;
  while ((m = regex.exec(t.content)) !== null) {
    allTokens.push({
      text: m[0],
      startIndex: t.startIndex + m.index,
      endIndex: t.startIndex + m.index + m[0].length,
    });
  }
}

const imageMap = {};
for (const item of imagePlaceholders) {
  if (item?.placeholder) {
    imageMap[item.placeholder] = item.publicImageUrl || (item.fileId ? `https://lh3.googleusercontent.com/d/${item.fileId}` : '');
  }
}

const placeholderGroups = {
  building_shelter: ['<<Bangunlink1>>', '<<Bangunlink2>>', '<<Bangunlink3>>', '<<Bangunlink4>>', '<<Bangunlink5>>'],
  building_pagar: ['<<Bangunpagar1>>', '<<Bangunpagar2>>', '<<Bangunpagar3>>', '<<Bangunpagar4>>', '<<Bangunpagar5>>'],
  building_pondasi: ['<<Pondasi1>>', '<<Pondasi2>>', '<<Pondasi3>>', '<<Pondasi4>>', '<<Pondasi5>>'],
  building_pos: ['<<Pos1>>', '<<Pos2>>', '<<Pos3>>', '<<Pos4>>', '<<Pos5>>'],
  tx: ['<<TX1>>', '<<TX2>>', '<<TX3>>', '<<TX4>>', '<<TX5>>'],
  head: ['<<Head1>>', '<<Head2>>', '<<Head3>>', '<<Head4>>', '<<Head5>>'],
  tv: ['<<TV1>>', '<<TV2>>', '<<TV3>>', '<<TV4>>', '<<TV5>>'],
  sf: ['<<SF1>>', '<<SF2>>', '<<SF3>>', '<<SF4>>', '<<SF5>>'],
  feed: ['<<Feed1>>', '<<Feed2>>', '<<Feed3>>', '<<Feed4>>', '<<Feed5>>'],
  tower: ['<<Ltower1>>', '<<Ltower2>>', '<<Ltower3>>', '<<Ltower4>>', '<<Ltower5>>'],
  mcb: ['<<MCB1>>', '<<MCB2>>', '<<MCB3>>', '<<MCB4>>', '<<MCB5>>'],
  pu: ['<<PU1>>', '<<PU2>>', '<<PU3>>', '<<PU4>>', '<<PU5>>'],
  ups: ['<<UPS1>>', '<<UPS2>>', '<<UPS3>>', '<<UPS4>>', '<<UPS5>>'],
  pla: ['<<PLA1>>', '<<PLA2>>', '<<PLA3>>', '<<PLA4>>', '<<PLA5>>'],
  actx: ['<<ACTX1>>', '<<ACTX2>>', '<<ACTX3>>', '<<ACTX4>>', '<<ACTX5>>'],
  genset: ['<<Genset1>>', '<<Genset2>>', '<<Genset3>>', '<<Genset4>>', '<<Genset5>>'],
  lruang: ['<<Lruang1>>', '<<Lruang2>>', '<<Lruang3>>', '<<Lruang4>>', '<<Lruang5>>'],
  lt: ['<<LT1>>', '<<LT2>>', '<<LT3>>', '<<LT4>>', '<<LT5>>'],
  gr: ['<<GR1>>', '<<GR2>>', '<<GR3>>', '<<GR4>>', '<<GR5>>'],
};

const tokenToGroup = {};
for (const [groupName, tokens] of Object.entries(placeholderGroups)) {
  tokens.forEach((token, index) => {
    tokenToGroup[token] = { groupName, index };
  });
}

const groupActiveCounts = {};
for (const [groupName, tokens] of Object.entries(placeholderGroups)) {
  groupActiveCounts[groupName] = tokens.filter(token => !!imageMap[token]).length;
}

function getImageSize(tokenText) {
  const meta = tokenToGroup[tokenText];
  if (!meta) return { width: 84, height: 84 };

  const activeCount = groupActiveCounts[meta.groupName] || 0;
  if (activeCount <= 1) return { width: 112, height: 112 };
  if (activeCount === 2) return { width: 102, height: 102 };
  if (activeCount === 3) return { width: 92, height: 92 };
  if (activeCount === 4) return { width: 82, height: 82 };
  return { width: 72, height: 72 };
}

const requests = [];
const inserted = [];
const removedOnly = [];
const groupedSummary = {};

allTokens.sort((a, b) => b.startIndex - a.startIndex);

for (const token of allTokens) {
  const imageUrl = imageMap[token.text];

  requests.push({
    deleteContentRange: {
      range: {
        startIndex: token.startIndex,
        endIndex: token.endIndex,
      },
    },
  });

  if (imageUrl) {
    const size = getImageSize(token.text);

    requests.push({
      insertInlineImage: {
        location: { index: token.startIndex },
        uri: imageUrl,
        objectSize: {
          width: { magnitude: size.width, unit: 'PT' },
          height: { magnitude: size.height, unit: 'PT' },
        },
      },
    });

    inserted.push({
      placeholder: token.text,
      width: size.width,
      height: size.height,
      ratio: '1:1',
      align: 'TEMPLATE_CONTROLLED',
      group: tokenToGroup[token.text]?.groupName || 'other',
      groupCount: tokenToGroup[token.text]?.groupName
        ? groupActiveCounts[tokenToGroup[token.text].groupName]
        : 0,
    });

    const groupName = tokenToGroup[token.text]?.groupName || 'other';
    if (!groupedSummary[groupName]) groupedSummary[groupName] = [];
    groupedSummary[groupName].push({
      placeholder: token.text,
      width: size.width,
      height: size.height,
      ratio: '1:1',
      align: 'TEMPLATE_CONTROLLED',
    });
  } else {
    removedOnly.push(token.text);
  }
}

if (requests.length === 0) {
  requests.push({
    replaceAllText: {
      containsText: {
        text: '[[NO_TOKEN_MATCH]]',
        matchCase: true,
      },
      replaceText: '',
    },
  });
}

return [{
  json: {
    documentId: base.documentId,
    docUrl: base.docUrl,
    reportName: base.reportName,
    recipientEmail: base.recipientEmail,
    requests,
    insertedPlaceholders: inserted,
    removedPlaceholders: removedOnly,
    smartGrouping: groupedSummary,
    totalTokensScanned: allTokens.length,
  },
}];

